package com.aoo.bcg.common.cache;import java.util.List;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class RedisLuaContractTest{@Test void enforcesKeyCountSlotNamespaceTimeoutAndResultType(){var contract=RedisAtomicKeyMigration.CONTRACT;contract.validate(List.of("prod:game:{room-1}:v1","prod:game:{room-1}:v2"));assertEquals(2,contract.keyCount());assertEquals(100,contract.timeout().toMillis());assertEquals(RedisLuaContract.ResultType.INTEGER,contract.resultType());assertThrows(IllegalArgumentException.class,()->contract.validate(List.of("prod:game:{one}:v1","prod:game:{two}:v2")));assertThrows(SecurityException.class,()->contract.validate(List.of("legacy:{one}:v1","legacy:{one}:v2")));}}
